00942: let ausdruckAktiv = 1;
00943: let _sonderLaeuft = false;
00944: function sonderausdruckZeigen(register, ausdruck, haltenMs){
00945:   if(_sonderLaeuft) return; // keine zwei Sequenzen gleichzeitig
00946:   haltenMs = haltenMs || 1400;
00947:   _sonderLaeuft = true;
00948:   $("mund-effekt").style.opacity = "0";
00949:   const stufeSrc = n => `/ausdruck_erweitert/${register}/${ausdruck}/frontal/stufe_0${n}.png`;
00950:   const wechsel = (neu, mitSchwung) => {
00951:     const sichtbar = ausdruckAktiv === 1 ? $("ausdruck-schicht") : $("ausdruck-schicht2");
00952:     const versteckt = ausdruckAktiv === 1 ? $("ausdruck-schicht2") : $("ausdruck-schicht");
00953:     if(sichtbar.getAttribute("src") === neu) return;
00954:     versteckt.src = neu;
00955:     // ⭐⭐ PERF-FIX 2026-09-11: gleiche Vor-Synchronisation wie bei
00956:     // kopfRollTick() oben -- atmen() schreibt Transform/Filter nur noch auf
00957:     // die per ausdruckAktiv aktuell sichtbare Ebene, die neu einblendende
00958:     // Ebene braucht den brandaktuellen Wert deshalb hier einmalig.
00959:     versteckt.style.transform = _atmenTransform;
00960:     versteckt.style.filter = _atmenFilter;
00961:     versteckt.style.opacity = "1";
00962:     sichtbar.style.opacity = "0";
00963:     ausdruckAktiv = ausdruckAktiv === 1 ? 2 : 1;
00964:     if(mitSchwung){
00965:       const rahmen = $("gesicht-rahmen");
00966:       rahmen.classList.remove("pose-wechsel");
00967:       requestAnimationFrame(() => rahmen.classList.add("pose-wechsel"));
00968:       setTimeout(() => rahmen.classList.remove("pose-wechsel"), 420);
00969:     }
00970:   };
00971:   const sauber = () => {
00972:     $("ausdruck-schicht").style.opacity = "0";
00973:     $("ausdruck-schicht2").style.opacity = "0";
00974:     $("mund-effekt").style.opacity = "1";
00975:     if(!mundAktivFrames) $("mund-effekt").src = `/mund_keyframes/${MUND_RUHE}.png`;
00976:     _sonderLaeuft = false;
00977:     gesichtNeuZeichnen(true);
00978:   };
00979:   let stufe = 0;
00980:   wechsel(stufeSrc(0), true);
00981:   const hoch = () => {
00982:     stufe++;
00983:     wechsel(stufeSrc(stufe), false);
00984:     if(stufe < 6) setTimeout(hoch, 90);
00985:     else setTimeout(runter, haltenMs);
00986:   };
00987:   const runter = () => {
00988:     stufe--;
00989:     wechsel(stufeSrc(stufe), false);
00990:     if(stufe > 0) setTimeout(runter, 90);
00991:     else setTimeout(sauber, 120); // letzte Stufe (= Neutralbild) kurz halten, dann Ebenen aus
00992:   };
00993:   setTimeout(hoch, 90);
